                    int choiceIndex = 0;
                    for (DataComponent item: ((DataChoice) cmdDef).getItemList())
                    {
                        SWEVirtualSensorControl controlInput = new SWEVirtualSensorControl(this, item, choiceIndex);
                        this.addControlInput(controlInput);
                        choiceIndex++;
